import json
with open('/app/resources/treasury_bulletin_1963_12.json', 'r') as f:
    data = json.load(f)
# Look for any table with 'exchange' or 'rate' in it
def find_in_dict(d, path=''):
    if isinstance(d, dict):
        for k, v in d.items():
            if 'exchange' in k.lower() or 'rate' in k.lower() or 'pound' in k.lower() or 'gbp' in k.lower():
                print(f'{path}.{k}: {v}')
            find_in_dict(v, f'{path}.{k}')
    elif isinstance(d, list):
        for i, item in enumerate(d[:3]):
            find_in_dict(item, f'{path}[{i}]')
find_in_dict(data)
"

