import json
with open('/app/resources/treasury_bulletin_1963_12.json', 'r') as f:
    data = json.load(f)
# Find any table with IFS or international financial statistics
def find_tables(d, path=''):
    if isinstance(d, dict):
        for k, v in d.items():
            if 'ifs' in k.lower() or 'international' in k.lower() or 'statistic' in k.lower():
                print(f'{path}.{k}')
            find_tables(v, f'{path}.{k}')
    elif isinstance(d, list):
        for i, item in enumerate(d[:5]):
            find_tables(item, f'{path}[{i}]')
find_tables(data)
"

